let products=read(PK,[]),settings=read(SK,{}),analyticsSettings=readAnalyticsSettings(),pantryItems=readPantry(),receipts=readReceipts(),receiptDraftLines=[],productCatalog=[],receiptPhotoUrl='',offers=[],stores=[],flyerLinks=[],foundStores=[],timer,activeStoreFilter="",offersLoadedAt=null,analysisCache=null,lastSyncAt=0;
const hydrateProduct=p=>({quantity:1,unit:'pz',priority:'normal',allowAlternatives:true,checked:false,notes:'',...p});
products=products.map(hydrateProduct);
const configured=()=>!!(String(settings.scriptUrl||'').trim()&&family(settings.familyCode));
function status(t='',c=''){$('syncStatus').textContent=t;$('syncStatus').className='sync-status '+c}
function invalidateAnalysis(){analysisCache=null;activePerfectPlan=null}
function saveLocal(){write(PK,products);invalidateAnalysis()}
const unitLabel=unit=>({pz:'pezzi',conf:'confezioni',kg:'kg',g:'g',l:'litri',ml:'ml'})[unit]||unit||'pezzi';
function savePantry(){writePantry(pantryItems)}
function pantryItemStatus(item){
 const expiry=daysToExpiry(item);if(expiry!=null&&expiry<0)return{tone:'expired',label:'Scaduto'};
 if(expiry!=null&&expiry<=7)return{tone:'expiring',label:expiry===0?'Scade oggi':`Scade tra ${expiry} giorni`};
 if(isLowStock(item))return{tone:'low',label:'Scorta bassa'};
 return{tone:'ok',label:'Disponibile'};
}
function renderPantryOverview(){
 const el=$('pantryOverview');if(!el)return;const summary=pantrySummary(pantryItems),low=pantryItems.filter(isLowStock).slice(0,4);
 el.innerHTML=`<article class="card pantry-overview"><div><h3 class="name">${summary.total} prodotti in dispensa</h3><p class="meta">${summary.low} sotto soglia · ${summary.expiring} in scadenza · ${summary.expired} scaduti</p>${low.length?`<small class="pantry-low-list">Da ricomprare: ${low.map(x=>esc(x.name)).join(', ')}</small>`:''}</div><button id="openPantry" class="btn primary">Apri dispensa</button></article>`;
 $('openPantry').onclick=openPantry;
}
function renderPantryDialog(){
 const summary=pantrySummary(pantryItems);$('pantrySummary').innerHTML=`<div><span>Prodotti</span><strong>${summary.total}</strong></div><div><span>Scorte basse</span><strong>${summary.low}</strong></div><div><span>In scadenza</span><strong>${summary.expiring}</strong></div>`;
 const sorted=[...pantryItems].sort((a,b)=>Number(isLowStock(b))-Number(isLowStock(a))||String(a.name).localeCompare(String(b.name),'it'));
 $('pantryItems').innerHTML=sorted.length?sorted.map(item=>{const st=pantryItemStatus(item);return`<article class="pantry-row ${st.tone}"><div class="pantry-main"><strong>${esc(item.name)}</strong><small>${esc(item.quantity)} ${esc(unitLabel(item.unit))}${item.expiryDate?' · scadenza '+new Date(item.expiryDate+'T12:00:00').toLocaleDateString('it-IT'):''}${item.store?' · '+esc(item.store):''}</small><span class="pantry-status">${esc(st.label)}</span></div><div class="pantry-controls"><button class="pantry-step" data-pantry-minus="${esc(item.id)}">−</button><button class="pantry-step" data-pantry-plus="${esc(item.id)}">＋</button><button class="textbtn" data-pantry-edit="${esc(item.id)}">Modifica</button><button class="textbtn danger" data-pantry-delete="${esc(item.id)}">Elimina</button></div></article>`}).join(''):'<div class="empty"><div style="font-size:2rem">📦</div><h3>Dispensa vuota</h3><p>Aggiungi le scorte che hai già in casa oppure trasferisci i prodotti presi dalla lista.</p></div>';
 document.querySelectorAll('[data-pantry-minus]').forEach(b=>b.onclick=()=>adjustPantry(b.dataset.pantryMinus,-1));
 document.querySelectorAll('[data-pantry-plus]').forEach(b=>b.onclick=()=>adjustPantry(b.dataset.pantryPlus,1));
 document.querySelectorAll('[data-pantry-edit]').forEach(b=>b.onclick=()=>openPantryItem(pantryItems.find(x=>x.id===b.dataset.pantryEdit)));
 document.querySelectorAll('[data-pantry-delete]').forEach(b=>b.onclick=()=>deletePantryItem(b.dataset.pantryDelete));
}
function openPantry(){renderPantryDialog();$('pantryDialog').showModal()}
function openPantryItem(item=null){
 $('pantryItemTitle').textContent=item?'Modifica scorta':'Aggiungi scorta';$('pantryId').value=item?.id||'';$('pantryProductId').value=item?.productId||'';$('pantryName').value=item?.name||'';$('pantryQuantity').value=item?.quantity??1;$('pantryUnit').value=item?.unit||'pz';$('pantryMinimum').value=item?.minimumQuantity??0;$('pantryExpiry').value=item?.expiryDate||'';$('pantryStore').value=item?.store||'';$('pantryPrice').value=item?.lastPrice??'';$('pantryNotes').value=item?.notes||'';$('pantryItemMsg').textContent='';$('pantryItemDialog').showModal();setTimeout(()=>$('pantryName').focus(),40);
}
function savePantryItem(){
 const name=$('pantryName').value.trim(),quantity=Number($('pantryQuantity').value),minimum=Number($('pantryMinimum').value);if(!name){$('pantryItemMsg').textContent='Inserisci il nome del prodotto.';return}if(!Number.isFinite(quantity)||quantity<0){$('pantryItemMsg').textContent='Inserisci una quantità valida.';return}
 const item=normalizePantryItem({id:$('pantryId').value||uid(),productId:$('pantryProductId').value,name,quantity,unit:$('pantryUnit').value,minimumQuantity:Number.isFinite(minimum)?minimum:0,expiryDate:$('pantryExpiry').value,store:$('pantryStore').value,lastPrice:$('pantryPrice').value,notes:$('pantryNotes').value,updatedAt:new Date().toISOString()});
 pantryItems=upsertPantry(pantryItems,item);savePantry();$('pantryItemDialog').close();renderPantryOverview();renderPantryDialog();status('Dispensa aggiornata.','success');
}
function adjustPantry(id,delta){const i=pantryItems.findIndex(x=>x.id===id);if(i<0)return;pantryItems[i]={...pantryItems[i],quantity:Math.max(0,Number(pantryItems[i].quantity||0)+delta),updatedAt:new Date().toISOString()};savePantry();renderPantryOverview();renderPantryDialog()}
function deletePantryItem(id){const item=pantryItems.find(x=>x.id===id);if(!item||!confirm(`Eliminare "${item.name}" dalla dispensa?`))return;pantryItems=pantryItems.filter(x=>x.id!==id);savePantry();renderPantryOverview();renderPantryDialog()}
function transferCheckedToPantry(){
 const checked=products.filter(p=>p.checked);if(!checked.length){alert('Spunta almeno un prodotto acquistato.');return}const plan=shoppingPlan();pantryItems=addPurchasedProducts(pantryItems,products,plan?.assignments||[]);savePantry();products=products.map(p=>p.checked?{...p,checked:false,updatedAt:new Date().toISOString()}:p);saveLocal();render();renderShoppingDialog();renderPantryDialog();status(`${checked.length} prodotti aggiunti alla dispensa.`, 'success');
}


function assistantContext(){
 let plans=[];try{plans=computePerfectPlans().plans||[]}catch{}
 return buildAssistantContext({products,pantry:pantryItems,receipts,offers,analyticsSettings,plans});
}
function assistantActionButton(label){return `<button class="btn secondary assistant-action" type="button" data-assistant-action="${esc(label)}">${esc(label)}</button>`}
function renderAssistantOverview(){
 const el=$('assistantOverview');if(!el)return;const r=weeklyReport(assistantContext());
 el.innerHTML=`<article class="card assistant-overview"><div class="assistant-spark">✨</div><div><h3 class="name">${esc(r.title)}</h3><p class="meta">Budget, lista, dispensa e offerte in un unico assistente.</p></div><button id="openAssistant" class="btn primary">Chiedi ora</button></article>`;
 $('openAssistant').onclick=openAssistant;
}
function appendAssistantMessage(kind,title,body,actions=[]){
 const box=$('assistantMessages');const article=document.createElement('article');article.className=`assistant-message ${kind}`;article.innerHTML=`<strong>${esc(title)}</strong><p>${esc(body).replace(/\n/g,'<br>')}</p>${actions.length?`<div class="assistant-actions">${actions.map(assistantActionButton).join('')}</div>`:''}`;box.appendChild(article);box.scrollTop=box.scrollHeight;bindAssistantActions();
}
function openAssistant(){
 $('assistantMessages').innerHTML='';appendAssistantMessage('assistant','Spesa Smart','Ciao! Posso analizzare budget, lista, dispensa, scadenze e supermercati.');$('assistantQuestion').value='';$('assistantDialog').showModal();
}
function askAssistant(question=null){
 const q=String(question??$('assistantQuestion').value).trim();if(!q)return;appendAssistantMessage('user','Tu',q);$('assistantQuestion').value='';const r=answerAssistant(q,assistantContext());setTimeout(()=>appendAssistantMessage('assistant',r.title,r.body,r.actions||[]),30);
}
function bindAssistantActions(){
 document.querySelectorAll('[data-assistant-action]').forEach(b=>b.onclick=()=>runAssistantAction(b.dataset.assistantAction));
}
function runAssistantAction(action){
 if(action==='Apri la dispensa'){openPantry();return}
 if(action==='Apri analisi'){openAnalytics();return}
 if(action==='Calcola la spesa migliore'){try{openSmartPlan()}catch(e){alert(e.message||'Piano non disponibile.')}return}
 if(action==='Inizia la spesa'){openShoppingDialog(shoppingPlan());return}
 if(action==='Vai alla lista'){$('assistantDialog').close();$('productsSection').scrollIntoView({behavior:'smooth'});return}
 if(action==='Aggiungi scorte basse alla lista'){const result=addLowStockToList(products,pantryItems);products=result.products;if(result.added.length){saveLocal();render();appendAssistantMessage('assistant','Lista aggiornata',`Aggiunti: ${result.added.join(', ')}.`)}else appendAssistantMessage('assistant','Nessun prodotto aggiunto','Le scorte basse risultano già presenti nella lista.');return}
 askAssistant(action);
}

function saveReceipts(){writeReceipts(receipts)}
function barRows(rows,total){if(!rows.length)return '<p class="meta">Dati non ancora disponibili.</p>';const max=Math.max(...rows.map(x=>Number(x.total)||0),1);return rows.map(x=>`<div class="analytics-row"><div><span>${esc(x.name)}</span><strong>${money(x.total)}</strong></div><div class="analytics-bar"><i style="width:${Math.max(3,Math.round(Number(x.total||0)/max*100))}%"></i></div></div>`).join('')}
function renderAnalyticsOverview(){
 const el=$('analyticsOverview');if(!el)return;const a=buildSpendingAnalytics(receipts,products),b=budgetStatus(a.monthTotal,analyticsSettings.monthlyBudget,analyticsSettings.warningPercent);
 const budgetText=b.budget?`${money(b.total)} su ${money(b.budget)} · ${b.percent}%`:'Imposta un budget mensile';
 el.innerHTML=`<article class="card analytics-overview"><div><h3 class="name">Spesa del mese: ${money(a.monthTotal)}</h3><p class="meta">${a.receiptCount} scontrini · media ${money(a.averageReceipt)} · ${esc(budgetText)}</p>${a.bestStore?`<small>Più spesa registrata da ${esc(a.bestStore.name)}: ${money(a.bestStore.total)}</small>`:''}</div><button id="openAnalytics" class="btn primary">Apri analisi</button></article>`;
 $('openAnalytics').onclick=openAnalytics;
}
function renderAnalyticsDialog(){
 const a=buildSpendingAnalytics(receipts,products),b=budgetStatus(a.monthTotal,analyticsSettings.monthlyBudget,analyticsSettings.warningPercent);$('monthlyBudget').value=analyticsSettings.monthlyBudget||'';
 $('analyticsKpis').innerHTML=`<div><span>Spesa mese</span><strong>${money(a.monthTotal)}</strong></div><div><span>Scontrini</span><strong>${a.receiptCount}</strong></div><div><span>Media scontrino</span><strong>${money(a.averageReceipt)}</strong></div><div class="${b.tone}"><span>${b.budget?'Budget residuo':'Budget'}</span><strong>${b.budget?money(b.remaining):'Non impostato'}</strong></div>${b.budget?`<div class="analytics-budget-wide"><div><span>Utilizzo budget</span><strong>${b.percent}%</strong></div><div class="budget-progress"><i style="width:${Math.min(100,b.percent)}%"></i></div>${b.over?`<small>Superato di ${money(b.over)}</small>`:''}</div>`:''}`;
 $('analyticsStores').innerHTML=barRows(a.byStore,a.monthTotal);$('analyticsCategories').innerHTML=barRows(a.byCategory,a.monthTotal);
 $('analyticsTrend').innerHTML=a.monthlyTrend.length?`<div class="trend-list">${a.monthlyTrend.map(x=>`<div><span>${new Date(x.month+'-01T12:00:00').toLocaleDateString('it-IT',{month:'short',year:'2-digit'})}</span><strong>${money(x.total)}</strong></div>`).join('')}</div>`:'<p class="meta">Servono scontrini di più mesi per mostrare l’andamento.</p>';
 $('analyticsProducts').innerHTML=a.topProducts.length?a.topProducts.map((x,i)=>`<div class="analytics-product"><span>${i+1}. ${esc(x.name)}</span><strong>${money(x.total)}</strong><small>${x.count} acquisti · ${x.quantity} unità</small></div>`).join(''):'<p class="meta">Nessun prodotto registrato questo mese.</p>';
}
function openAnalytics(){renderAnalyticsDialog();$('analyticsDialog').showModal()}
function saveAnalyticsBudget(){const v=Math.max(0,Number($('monthlyBudget').value)||0);analyticsSettings={...analyticsSettings,monthlyBudget:v};writeAnalyticsSettings(analyticsSettings);renderAnalyticsDialog();renderAnalyticsOverview();$('analyticsMsg').textContent=v?`Budget mensile impostato a ${money(v)}.`:'Budget disattivato.'}
function renderReceiptsOverview(){
 const el=$('receiptsOverview');if(!el)return;const x=receiptsSummary(receipts);
 el.innerHTML=`<article class="card receipt-overview"><div><h3 class="name">${x.monthCount} scontrini questo mese</h3><p class="meta">Spesa registrata: <strong>${money(x.monthTotal)}</strong> · ${Math.round(x.products)} articoli</p></div><button id="openReceipts" class="btn primary">Apri acquisti</button></article>`;
 $('openReceipts').onclick=openReceipts;
}
function renderReceiptsDialog(){
 const x=receiptsSummary(receipts);$('receiptsSummary').innerHTML=`<div><span>Scontrini</span><strong>${x.count}</strong></div><div><span>Questo mese</span><strong>${money(x.monthTotal)}</strong></div><div><span>Articoli</span><strong>${Math.round(x.products)}</strong></div>`;
 $('receiptsList').innerHTML=receipts.length?[...receipts].sort((a,b)=>String(b.date).localeCompare(String(a.date))).map(r=>`<article class="receipt-row"><div><strong>${esc(r.store||'Supermercato')}</strong><small>${new Date(r.date+'T12:00:00').toLocaleDateString('it-IT')} · ${r.lines.length} righe${r.note?' · '+esc(r.note):''}</small></div><div class="receipt-row-actions"><strong>${money(r.total)}</strong><button class="textbtn" data-receipt-edit="${esc(r.id)}">Modifica</button><button class="textbtn danger" data-receipt-delete="${esc(r.id)}">Elimina</button></div></article>`).join(''):'<div class="empty"><div style="font-size:2rem">🧾</div><h3>Nessuno scontrino</h3><p>Registra il primo acquisto e aggiorna la dispensa in pochi passaggi.</p></div>';
 document.querySelectorAll('[data-receipt-edit]').forEach(b=>b.onclick=()=>openReceipt(receipts.find(x=>x.id===b.dataset.receiptEdit)));
 document.querySelectorAll('[data-receipt-delete]').forEach(b=>b.onclick=()=>deleteReceipt(b.dataset.receiptDelete));
}
function openReceipts(){renderReceiptsDialog();$('receiptsDialog').showModal()}
function emptyReceiptLine(){return{id:uid(),name:'',quantity:1,unit:'pz',unitPrice:0,addToPantry:true}}
function renderReceiptLines(){
 $('receiptLines').innerHTML=receiptDraftLines.map(l=>{const rec=l.recognition,confidence=rec?.confidence??null,tone=confidence==null?'':confidence>=95?'good':confidence>=75?'warn':'bad',candidateOptions=(rec?.candidates||[]).map(x=>`<option value="${esc(x.item.id)}" ${x.item.id===l.productId?'selected':''}>${esc(x.item.name)} · ${Math.round(x.score*100)}%</option>`).join('');return`<div class="receipt-line-wrap"><div class="receipt-line" data-line-id="${esc(l.id)}"><input class="receipt-line-name" value="${esc(l.name)}" placeholder="Prodotto"><input class="receipt-line-qty" type="number" min="0.01" step="0.01" value="${esc(l.quantity)}" aria-label="Quantità"><select class="receipt-line-unit"><option value="pz" ${l.unit==='pz'?'selected':''}>pz</option><option value="conf" ${l.unit==='conf'?'selected':''}>conf</option><option value="kg" ${l.unit==='kg'?'selected':''}>kg</option><option value="g" ${l.unit==='g'?'selected':''}>g</option><option value="l" ${l.unit==='l'?'selected':''}>L</option><option value="ml" ${l.unit==='ml'?'selected':''}>ml</option></select><input class="receipt-line-price" type="number" min="0" step="0.01" value="${l.unitPrice||''}" placeholder="€ / unità" aria-label="Prezzo unitario"><label class="receipt-pantry-check" title="Aggiungi alla dispensa"><input type="checkbox" ${l.addToPantry?'checked':''}>📦</label><button class="icon receipt-line-remove" type="button" aria-label="Elimina riga">✕</button></div>${confidence!=null?`<div class="receipt-recognition ${tone}"><span>${confidence>=95?'● Riconosciuto automaticamente':confidence>=75?'● Da confermare':'● Prodotto nuovo'}${confidence?` · ${confidence}%`:''}</span>${candidateOptions?`<select class="receipt-candidate"><option value="">Mantieni: ${esc(l.name)}</option>${candidateOptions}</select>`:'<span>Verrà creato nel catalogo personale</span>'}</div>`:''}</div>`}).join('');
 document.querySelectorAll('.receipt-line').forEach(row=>{const id=row.dataset.lineId,wrap=row.closest('.receipt-line-wrap'),update=()=>{const l=receiptDraftLines.find(x=>x.id===id);if(!l)return;l.name=row.querySelector('.receipt-line-name').value;l.quantity=Number(row.querySelector('.receipt-line-qty').value)||1;l.unit=row.querySelector('.receipt-line-unit').value;l.unitPrice=Number(row.querySelector('.receipt-line-price').value)||0;l.addToPantry=row.querySelector('.receipt-pantry-check input').checked;updateReceiptTotal()};row.querySelectorAll('input,select').forEach(x=>x.oninput=update);wrap?.querySelector('.receipt-candidate')?.addEventListener('change',e=>{const l=receiptDraftLines.find(x=>x.id===id),item=productCatalog.find(x=>x.id===e.target.value);if(l&&item){l.productId=item.id;l.name=item.name;l.recognition={...(l.recognition||{}),confidence:100,status:'auto'};renderReceiptLines()}});row.querySelector('.receipt-line-remove').onclick=()=>{receiptDraftLines=receiptDraftLines.filter(x=>x.id!==id);if(!receiptDraftLines.length)receiptDraftLines=[emptyReceiptLine()];renderReceiptLines()}});updateReceiptTotal();
}
function updateReceiptTotal(){const total=receiptDraftLines.reduce((s,l)=>s+(Number(l.quantity)||0)*(Number(l.unitPrice)||0),0);$('receiptTotal').textContent=money(total)}
function openReceipt(receipt=null){
 $('receiptTitle').textContent=receipt?'Modifica scontrino':'Nuovo scontrino';$('receiptId').value=receipt?.id||'';$('receiptStore').value=receipt?.store||'';$('receiptDate').value=receipt?.date||new Date().toISOString().slice(0,10);$('receiptNote').value=receipt?.note||'';$('receiptToPantry').checked=!receipt;$('receiptPhoto').value='';if(receiptPhotoUrl)URL.revokeObjectURL(receiptPhotoUrl);receiptPhotoUrl='';$('receiptPhotoPreview').hidden=true;$('receiptPhotoPreview').innerHTML='';receiptDraftLines=receipt?.lines?.map(x=>({...x}))||[emptyReceiptLine()];$('receiptMsg').textContent='';$('receiptOcrStatus').textContent='';$('receiptOcrDetails').hidden=true;$('receiptOcrText').textContent='';$('analyzeReceipt').disabled=false;renderReceiptLines();$('receiptDialog').showModal();setTimeout(()=>$('receiptStore').focus(),40)
}
function saveReceipt(){
 const store=$('receiptStore').value.trim(),date=$('receiptDate').value;if(!store){$('receiptMsg').textContent='Inserisci il supermercato.';return}const valid=receiptDraftLines.filter(x=>String(x.name).trim()&&Number(x.quantity)>0&&Number(x.unitPrice)>=0);if(!valid.length){$('receiptMsg').textContent='Inserisci almeno un prodotto con quantità e prezzo.';return}
 productCatalog=learnReceiptLines(valid,productCatalog);
 const existingId=$('receiptId').value,receipt=normalizeReceipt({id:existingId||uid(),store,date,note:$('receiptNote').value,lines:valid,createdAt:receipts.find(x=>x.id===existingId)?.createdAt});receipts=upsertReceipt(receipts,receipt);saveReceipts();if($('receiptToPantry').checked&&!existingId){pantryItems=receiptToPantry(receipt,pantryItems,normalizePantryItem,upsertPantry);savePantry()}
 $('receiptDialog').close();renderReceiptsOverview();renderReceiptsDialog();renderPantryOverview();status('Scontrino salvato'+($('receiptToPantry').checked&&!existingId?' e dispensa aggiornata.':'.'),'success')
}
function deleteReceipt(id){const r=receipts.find(x=>x.id===id);if(!r||!confirm(`Eliminare lo scontrino di ${r.store}?`))return;receipts=receipts.filter(x=>x.id!==id);saveReceipts();renderReceiptsOverview();renderReceiptsDialog()}
function previewReceiptPhoto(){const file=$('receiptPhoto').files?.[0],box=$('receiptPhotoPreview');if(receiptPhotoUrl)URL.revokeObjectURL(receiptPhotoUrl);if(!file){box.hidden=true;box.innerHTML='';return}receiptPhotoUrl=URL.createObjectURL(file);box.innerHTML=`<img src="${receiptPhotoUrl}" alt="Anteprima scontrino">`;box.hidden=false}
async function analyzeReceiptPhoto(){const file=$('receiptPhoto').files?.[0],btn=$('analyzeReceipt'),st=$('receiptOcrStatus');if(!file){st.textContent='Seleziona prima una foto.';return}btn.disabled=true;st.textContent='Caricamento OCR…';try{const text=await recognizeReceiptImage(file,(pct,statusText)=>{st.textContent=pct==null?'Preparazione OCR…':`Lettura ${pct}%`});const parsed=parseReceiptText(text);$('receiptOcrText').textContent=text||'Nessun testo riconosciuto';$('receiptOcrDetails').hidden=false;if(parsed.store&&!$('receiptStore').value.trim())$('receiptStore').value=parsed.store;if(parsed.date)$('receiptDate').value=parsed.date;if(parsed.lines.length){const current=receiptDraftLines.filter(x=>String(x.name||'').trim()||Number(x.unitPrice)>0);productCatalog=buildProductCatalog({products,pantry:pantryItems,receipts,offers});const recognized=recognizeReceiptLines(parsed.lines,productCatalog);receiptDraftLines=[...current,...recognized.map(x=>({...x,id:uid()}))];renderReceiptLines();const auto=recognized.filter(x=>x.recognition.status==='auto').length,verify=recognized.filter(x=>x.recognition.status==='verify').length,unknown=recognized.length-auto-verify;st.textContent=`${auto} riconosciuti automaticamente · ${verify} da verificare · ${unknown} nuovi. Premi Salva per inserirli in acquisti e dispensa.`}else st.textContent='Testo letto, ma nessuna riga prodotto riconosciuta. Puoi inserirle manualmente.'}catch(err){console.error(err);st.textContent=err?.message||'Analisi non riuscita.'}finally{btn.disabled=false}}

function stateKey(){return [products.map(p=>[p.id,p.updatedAt,p.name,p.quantity,p.unit].join(':')).join(','),offers.length,stores.filter(s=>s.selected).map(s=>s.id).sort().join(',')].join('|')}
function baseAnalysis(){const key=stateKey();if(analysisCache?.key===key)return analysisCache;const selectedOffers=selectedStoreOffers(offers),dealData=analyzeDeals(products,selectedOffers);analysisCache={key,selectedOffers,dealData,dealMap:new Map(dealData.matches.map(x=>[x.product.id,x]))};return analysisCache}
